def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    rich_pressure = 0.0
    desperate_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) > 300 and opp.get('hp', 0) >= 4:
                rich_pressure = max(rich_pressure, float(bid))
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 0) <= 2:
            desperate_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    live_count = len(alive_opponents)

    scarcity = 0.0
    if supply <= 16:
        scarcity = 1.0
    elif supply <= 18:
        scarcity = 0.7
    elif supply <= 21:
        scarcity = 0.35
    else:
        scarcity = 0.1

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.45
    if no_water >= 2:
        urgency += 1.0
    elif no_water >= 1:
        urgency += 0.55

    pressure_bid = highest_prev
    if rich_pressure > pressure_bid:
        pressure_bid = rich_pressure

    if urgency >= 1.4:
        target = max(DAILY_SALARY * 0.95, pressure_bid + 3.0)
    elif scarcity >= 0.9:
        target = max(DAILY_SALARY * 0.82, pressure_bid * 0.92 + 2.0)
    elif scarcity >= 0.6:
        target = max(DAILY_SALARY * 0.62, pressure_bid * 0.72 + 1.5)
    else:
        target = max(DAILY_SALARY * 0.28, pressure_bid * 0.42 + 1.0)

    if desperate_count >= max(1, live_count - 1):
        target += 4.0

    if day >= 8 and hp >= 5 and no_water == 0 and supply >= 20:
        target *= 0.82

    if budget < DAILY_SALARY * 2:
        target = min(target, budget * 0.7)
    elif budget > DAILY_SALARY * 8 and urgency < 1.0 and scarcity < 0.6:
        target = min(target, DAILY_SALARY * 0.75)

    floor_bid = 0.0
    if urgency >= 1.0:
        floor_bid = DAILY_SALARY * 0.72
    elif scarcity >= 0.6:
        floor_bid = DAILY_SALARY * 0.4
    else:
        floor_bid = DAILY_SALARY * 0.18

    bid = max(floor_bid, target)
    bid = min(budget, bid)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents are alive, bid conservatively
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate aggressiveness from yesterday
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
    else:
        highest_prev_bid = 0.0

    # Supply pressure heuristic: higher supply -> lower need to outbid
    # Normalize supply to [0,1]
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Base target bid: aim around a fraction of salary, adjusted by supply and yesterday aggressiveness
    # If opponents were bidding very high yesterday, we must match more.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base = DAILY_SALARY * (0.75 - 0.25 * supply_norm)
    elif highest_prev_bid >= DAILY_SALARY * 0.65:
        base = DAILY_SALARY * (0.6 - 0.15 * supply_norm)
    else:
        base = DAILY_SALARY * (0.52 - 0.1 * supply_norm)

    # Urgency adjustment based on our HP and no_water_days
    # If we're already in danger, bid higher to secure water.
    if hp <= 2.5:
        base *= 1.35
    elif hp <= 4.0:
        base *= 1.15

    if no_water_days >= 2:
        base *= 1.2
    elif no_water_days == 1:
        base *= 1.08

    # If supply is low (near MIN_SUPPLY), water is scarce -> slightly more aggressive
    if supply <= (MIN_SUPPLY + 1.0):
        base *= 1.12

    # Cap by budget; also avoid bidding absurdly above what salary suggests
    # Keep a floor to not get shut out when we need water.
    min_bid = 0.0
    if hp <= 4.0 or no_water_days >= 2:
        min_bid = DAILY_SALARY * 0.35
    else:
        min_bid = DAILY_SALARY * 0.25

    bid = max(min_bid, base)
    bid = min(bid, budget)

    # Final safety clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)
